const fs = require('node:fs');
const dir = '/work/workspace/deliverable';
const libDir = '/work/workspace/library';
const libFiles = fs.readdirSync(libDir);
const libText = Object.fromEntries(libFiles.map(f => [f, fs.readFileSync(libDir + '/' + f, 'utf8')]));
const allLib = Object.values(libText).join('\n');

const delivFiles = fs.readdirSync(dir);
const issues = [];
for (const f of delivFiles) {
  const txt = fs.readFileSync(dir + '/' + f, 'utf8');
  // 1. every library/<name> token must exist
  for (const m of txt.matchAll(/library\/([A-Za-z0-9_.\-]+)/g)) {
    if (!libFiles.includes(m[1])) issues.push(`${f}: bad library ref "library/${m[1]}"`);
  }
  // 2. statutory cites used must appear in library text
  const cites = new Set();
  for (const m of txt.matchAll(/§+\s*([0-9]{2,3}[a-z]?\(?[a-z0-9)(\s]*)/g)) cites.add(m[1].replace(/\s+/g,' ').trim());
  for (const c of cites) {
    const core = c.replace(/\(.*$/,'').trim(); // section number w/o subsection
    if (!allLib.includes('§' + core) && !allLib.includes(core)) issues.push(`${f}: cite "§${c}" not found in library text`);
  }
  // 3. rule cites
  for (const m of txt.matchAll(/300[23]\(c\)/g)) if (!allLib.includes(m[0])) issues.push(`${f}: ${m[0]} missing in library`);
  // 4. case cite
  if (txt.includes('Kmart') && !allLib.includes('Kmart')) issues.push(`${f}: Kmart not in library`);
}
// 5. JSON schema keys check
const j = JSON.parse(fs.readFileSync(dir + '/claim_analysis.json','utf8'));
const expected = ["claim_total","priority_claim_503b9","general_unsecured","stay_violations","reclamation_available","preference_exposure_net","recommended_actions"];
const extra = Object.keys(j).filter(k=>!expected.includes(k));
const missing = expected.filter(k=>!(k in j));
if (extra.length||missing.length) issues.push(`claim_analysis.json keys extra=${extra} missing=${missing}`);
if (j.claim_total !== j.priority_claim_503b9 + j.general_unsecured) issues.push('json totals mismatch');
// reclamation_available type
if (typeof j.reclamation_available !== 'boolean') issues.push('reclamation_available not boolean: '+JSON.stringify(j.reclamation_available).slice(0,80));

return {files: delivFiles, issues: issues.length ? issues : 'ALL CHECKS PASS', json: {claim_total:j.claim_total, p:j.priority_claim_503b9, g:j.general_unsecured, net:j.preference_exposure_net, recl:j.reclamation_available}};

